using Microsoft.Extensions.Configuration;

var builder = DistributedApplication.CreateBuilder(args);
// Optional local secrets generated by services/security/tools/SecuritySetup. Environment/configuration can override them.
var localSecrets = Path.GetFullPath(Path.Combine(builder.Environment.ContentRootPath, "../../../.secrets/security.json"));
builder.Configuration.AddJsonFile(localSecrets, optional: true).AddEnvironmentVariables();

var downloadReplicas = int.TryParse(builder.Configuration["DownloadReplicas"], out var replicas) ? replicas : 3;

builder.AddDockerComposeEnvironment("compose")
    .WithDashboard(dashboard => dashboard.WithHostPort(18888))
    .ConfigureComposeFile(file => ComposeAjustes.Arquivo(file, downloadReplicas));

var redisPassword = builder.AddParameter("redis-password", "root123", secret: true);
var mysqlPassword = builder.AddParameter("mysql-password", "root123", secret: true);
var signingKey = builder.AddParameter("security-signing-key", secret: true);
var internalKey = builder.AddParameter("identity-internal-key", secret: true);
var adminToken = builder.AddParameter("identity-admin-token", secret: true);

var redis = builder.AddRedis("redis", port: 6379, password: redisPassword)
    .WithoutHttpsCertificate()
    .WithContainerRuntimeArgs("--tmpfs", "/data")
    .WithLifetime(ContainerLifetime.Persistent);

var kafka = builder.AddKafka("kafka", port: 9092)
    .WithDataVolume("youtubesd-kafka-data")
    .WithLifetime(ContainerLifetime.Persistent)
    .WithKafkaUI(ui => ui
        .WithHostPort(8090)
        .WithLifetime(ContainerLifetime.Persistent));

var kafkaInit = builder.AddContainer("kafka-init", "confluentinc/confluent-local", "8.2.0")
    .WithBindMount("../../../infra/kafka", "/scripts", isReadOnly: true)
    .WithEntrypoint("/bin/bash")
    .WithArgs("/scripts/create-topics.sh")
    .WithEnvironment("KAFKA_BOOTSTRAP_SERVERS", "kafka:9093")
    .WaitFor(kafka);

var mysql = builder.AddMySql("mysql", password: mysqlPassword, port: 3306)
    .WithDataVolume("youtubesd-mysql-data")
    .WithLifetime(ContainerLifetime.Persistent);

var downloadDb = mysql.AddDatabase("downloadDb", "download_db");
var identityDb = mysql.AddDatabase("identityDb", "identity_db");
var securityDb = mysql.AddDatabase("securityDb", "security_db");

var ministack = builder.AddContainer("ministack", "ministackorg/ministack", "1.5.43")
    .WithHttpEndpoint(port: 4566, targetPort: 4566)
    .WithEnvironment("S3_PERSIST", "1")
    .WithEnvironment("S3_DATA_DIR", "/data/s3")
    .WithEnvironment("PERSIST_STATE", "1")
    .WithEnvironment("STATE_DIR", "/data/state")
    .WithVolume("youtubesd-ministack-data", "/data")
    .WithBindMount("../../../infra/ministack/ready.d", "/etc/localstack/init/ready.d", isReadOnly: true)
    .WithHttpHealthCheck("/_ministack/health")
    .WithLifetime(ContainerLifetime.Persistent);

var identity = builder.AddProject<Projects.identity>("identityService")
    .WithHttpHealthCheck("/health")
    .WithReference(identityDb).WaitFor(identityDb)
    .WithReference(kafka).WaitFor(kafka)
    .WaitForCompletion(kafkaInit)
    .WithEnvironment("Identity__InternalApiKey", internalKey)
    .WithEnvironment("Identity__AdminToken", adminToken);

var security = builder.AddProject<Projects.Security>("securityService")
    .WithHttpHealthCheck("/health")
    .WithReference(securityDb).WaitFor(securityDb)
    .WithReference(identity).WaitFor(identity)
    .WithEnvironment("Security__SigningKeyBase64", signingKey)
    .WithEnvironment("Security__IdentityInternalApiKey", internalKey);

// Reference the signing service directly, avoiding a dependency cycle through the gateway.
identity.WithReference(security)
    .WithEnvironment("Jwt__JwksUri", "http://securityService/api/auth/.well-known/jwks.json");

var upload = builder.AddProject<Projects.upload>("uploadService")
    .WithHttpHealthCheck("/health")
    .WithReference(security)
    .WithEnvironment("Jwt__JwksUri", "http://securityService/api/auth/.well-known/jwks.json");

var gateway = builder.AddProject<Projects.YoutubeOrchestrador_Gateway>("gateway")
    .WithHttpHealthCheck("/health")
    .WithReference(upload)
    .WaitFor(upload)
    .WithReference(identity)
    .WaitFor(identity)
    .WithReference(security).WaitFor(security);

for (var i = 1; i <= downloadReplicas; i++)
{
    var name = $"download-{i}";

    var download = builder.AddDockerfile(name, "../../../services/download")
        .WithHttpEndpoint(port: 8400 + i, targetPort: 8080)
        .WithHttpHealthCheck("/health")
        .WithContainerRuntimeArgs("--memory", "768m")
        .WithEnvironment("INSTANCE_ID", name)
        .WithEnvironment("SPRING_DATASOURCE_URL", "jdbc:mysql://mysql:3306/download_db")
        .WithEnvironment("SPRING_DATASOURCE_USERNAME", "root")
        .WithEnvironment("SPRING_DATASOURCE_PASSWORD", mysqlPassword)
        .WithEnvironment("SPRING_DATA_REDIS_HOST", "redis")
        .WithEnvironment("SPRING_DATA_REDIS_PORT", "6379")
        .WithEnvironment("SPRING_DATA_REDIS_PASSWORD", redisPassword)
        .WithEnvironment("SPRING_KAFKA_BOOTSTRAP_SERVERS", "kafka:9093")
        .WithEnvironment("AWS_ENDPOINT_URL", "http://ministack:4566")
        .WithEnvironment("AWS_REGION", "us-east-1")
        .WithEnvironment("AWS_ACCESS_KEY_ID", "test")
        .WithEnvironment("AWS_SECRET_ACCESS_KEY", "test")
        .WithEnvironment("AUTH_MODE", "jwt")
        .WithReference(security.GetEndpoint("http"))
        .WithEnvironment("JWT_JWKS_URI", ReferenceExpression.Create($"{security.GetEndpoint("http")}/api/auth/.well-known/jwks.json"))
        .WithEnvironment("JWT_ISSUER", "youtubesd-security")
        .WithEnvironment("JWT_AUDIENCE", "youtubesd-api")
        .WaitFor(security)
        .WaitFor(redis)
        .WaitFor(downloadDb)
        .WaitForCompletion(kafkaInit)
        .WaitFor(ministack);

    gateway
        .WithReference(download.GetEndpoint("http"))
        .WithEnvironment($"ReverseProxy__Clusters__download__Destinations__{name}__Address", $"http://{name}")
        .WaitFor(download);
}

builder.Build().Run();
